class Book::AccessImport
  Result = Struct.new(:accesses, :duplicate_index)

  def initialize(book, grants)
    @book, @grants = book, grants
  end

  def import
    new_grants, duplicate_index = fresh_grants
    return Result.new([], duplicate_index) if duplicate_index

    accesses = insert(new_grants)
    accesses.each { |access| Book::AccessNotificationJob.perform_later(access) }

    Result.new(accesses, nil)
  end

  private
    # One read to tell the sheet's names apart from the ones already on the book.
    # Scales with the roster, but keeps every write a single round trip.
    def fresh_grants
      taken_user_ids = Set.new(@book.accesses.where(user_id: granted_user_ids).pluck(:user_id))
      new_grants = []

      @grants.each_with_index do |grant, index|
        return [ nil, index ] unless Access.levels.key?(grant[:level].to_s)
        return [ nil, index ] unless taken_user_ids.add?(grant[:user_id])

        new_grants << grant
      end

      [ new_grants, nil ]
    end

    # A single statement, however long the roster is.
    def insert(grants)
      @book.accesses.insert_all!(grants.collect { |grant|
        { user_id: grant[:user_id], level: grant[:level].to_s }
      })

      @book.accesses.where(user_id: grants.map { |grant| grant[:user_id] }).index_by(&:user_id)
        .values_at(*grants.map { |grant| grant[:user_id] }).compact
    end

    def granted_user_ids
      @grants.map { |grant| grant[:user_id] }
    end
end
